  function validJournal(){return state.journal.filter(x=>!x.legacyInvalid&&x.total>0&&x.correct<=x.total);}
  function accuracy(){const j=validJournal(),t=j.reduce((a,x)=>a+x.total,0);return t?Math.round(j.reduce((a,x)=>a+x.correct,0)/t*100):0;}
  function minutes(){return state.journal.reduce((a,x)=>a+(Number(x.minutes)||0),0);}
  function weekStats(w=nextSession().week){const ids=new Set(state.plan.filter(x=>x.week===w).map(x=>x.id)),rows=state.journal.filter(x=>ids.has(x.sessionId));return{sessions:rows.length,minutes:rows.reduce((a,x)=>a+x.minutes,0)};}
  function streak(){let n=0;for(let w=Math.max(1,nextSession().week-1);w>=1;w--){if(weekStats(w).sessions>=state.profile.weeklySessionsGoal)n++;else break;}return n;}
  function latestResult(sessionId,type){return [...state.practiceResults].reverse().find(x=>x.sessionId===sessionId&&x.type===type&&x.contentVersion===window.SESSION_CONTENT.version);}
