  function advanceTimer(){
    if(!timer.running)return false;
    const now=Date.now();
    let delta=Math.max(0,Math.floor((now-timer.startedAt)/1000));
    if(!delta)return false;
    timer.startedAt+=delta*1000;
    if(timer.mode!=='focus'){timer.elapsed+=delta;return false;}
    timer.focusSeconds||=timerDuration(state.settings.focusMinutes,25,180)*60;
    timer.breakSeconds||=timerDuration(state.settings.breakMinutes,5,60)*60;
    let transitioned=false;
    while(delta>0){
      const cycle=timer.focusSeconds+timer.breakSeconds;
      if(timer.phase==='focus'&&timer.phaseElapsed===0&&delta>=cycle){const cycles=Math.floor(delta/cycle);timer.elapsed+=cycles*timer.focusSeconds;timer.completedFocus+=cycles;delta-=cycles*cycle;transitioned=true;continue;}
      const duration=timer.phase==='break'?timer.breakSeconds:timer.focusSeconds;
      const consumed=Math.min(delta,Math.max(0,duration-timer.phaseElapsed));
      if(timer.phase==='focus')timer.elapsed+=consumed;
      timer.phaseElapsed+=consumed;delta-=consumed;
      if(timer.phaseElapsed>=duration){if(timer.phase==='focus'){timer.completedFocus++;timer.phase='break';}else timer.phase='focus';timer.phaseElapsed=0;transitioned=true;}
    }
    if(transitioned)persistTimer();
    return transitioned;
  }
  function timerSeconds(){advanceTimer();return timer.elapsed;}
